
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_camh_b3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_camh_b3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.513568777363239e+00, -3.447020531069904e+00, -3.353818676033307e+00, -3.224810453734349e+00, -3.049223633511208e+00, -2.815938171791531e+00, -2.516454978034315e+00, -2.150091307192024e+00, -1.730310189702779e+00, -1.285570626569789e+00, -8.460811302827927e-01, -5.556929997565122e-01, -4.738505591917471e-01, -3.864462843626303e-01, -2.678131512606362e-01, -1.525226241845145e-01, -7.953221514986378e-02, -5.027380094321206e-02, -3.100140270219611e-02, -2.092231171817806e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


